parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "candidate_strengths": {
      "type": "array",
      "description": "Top strengths or relevant qualifications of the candidate.",
      "items": {
        "type": "string"
      }
    },

    "candidate_weaknesses": {
      "type": "array",
      "description": "Areas where candidate is lacking or mismatched.",
      "items": {
        "type": "string"
      }
    },

    "risk_factor": {
      "type": "object",
      "properties": {
        "score": {
          "type": "string",
          "enum": ["Low", "Medium", "High"]
        },
        "worst_case": {
          "type": "string"
        }
      },
      "required": [
        "score",
        "worst_case"
      ]
    },

    "reward_factor": {
      "type": "object",
      "properties": {
        "score": {
          "type": "string",
          "enum": ["Low", "Medium", "High"]
        },

        "best_case": {
          "type": "string"
        },

        "fit_type": {
          "type": "string",
          "enum": [
            "Short-term",
            "Long-term"
          ]
        }
      },

      "required": [
        "score",
        "best_case",
        "fit_type"
      ]
    },

    "overall_fit_rating": {
      "type": "integer",
      "minimum": 0,
      "maximum": 10,
      "description": "Overall fit score from 0 to 10 without decimals."
    },

    "justification_for_rating": {
      "type": "string"
    },

    "skill_gap_analysis": {
      "type": "object",
      "description": "Generate ONLY when overall_fit_rating is LESS than 5",

      "properties": {

        "missing_skills": {
          "type": "array",
          "description": "List important required skills the candidate does not have.",
          "items": {
            "type": "string"
          }
        },

        "missing_tools": {
          "type": "array",
          "description": "List missing tools, platforms, IDEs, or technologies.",
          "items": {
            "type": "string"
          }
        },

        "improvement_areas": {
          "type": "array",

          "description": "Generate actionable learning suggestions in sentence format like 'Learn embedded C/C++ programming', 'Acquire microcontroller and firmware development skills', 'Understand PCB design basics'",

          "items": {
            "type": "string"
          }
        }

      },

      "required": [
        "missing_skills",
        "missing_tools",
        "improvement_areas"
      ]
    },

    "interview_questions": {
      "type": "array",

      "description": "Generate EXACTLY 5 questions ONLY when overall_fit_rating is GREATER than or EQUAL to 5",

      "minItems": 5,
      "maxItems": 5,

      "items": {

        "type": "object",

        "properties": {

          "category": {
            "type": "string",

            "enum": [
              "Projects",
              "Technical Skills",
              "Experience",
              "Tools",
              "Problem Solving"
            ]
          },

          "question": {
            "type": "string"
          }

        },

        "required": [
          "category",
          "question"
        ]
      }
    }

  },

  "required": [
    "candidate_strengths",
    "candidate_weaknesses",
    "risk_factor",
    "reward_factor",
    "overall_fit_rating",
    "justification_for_rating"
  ]
}

